    "code_example": "import { Component } from '@angular/core';\nimport { CommonModule } from '@angular/common';\nimport { TarjetaUsuarioComponent } from './tarjeta-usuario.component';\n\n@Component({\n  selector: 'app-perfil',\n  standalone: true,\n  imports: [CommonModule, TarjetaUsuarioComponent],\n  template: `<app-tarjeta-usuario [nombre]=\"'Carlos'\" />`\n})\nexport class PerfilComponent {}",
